import java.io.BufferedInputStream
import java.io.PrintWriter
import java.util.StringTokenizer
import kotlin.system.exitProcess

const val M: Long = 1_000_000_007L

data class Co(var v: Long) {
    fun pow(n0: Long): Co {
        var n = n0
        var a = Co(v)
        var res = Co(1L)
        while (n > 0) {
            if ((n and 1L) == 1L) {
                res *= a
            }
            a *= a
            n = n shr 1
        }
        return res
    }

    operator fun plus(other: Co): Co =
        Co(((this.v + other.v) % M + M) % M)

    operator fun minus(other: Co): Co =
        Co(((this.v - other.v) % M + M) % M)

    operator fun times(other: Co): Co =
        Co(((this.v * other.v) % M + M) % M)

    operator fun div(other: Co): Co =
        this * other.pow(M - 2)

    operator fun plusAssign(other: Co) {
        val res = this + other
        this.v = res.v
    }

    operator fun minusAssign(other: Co) {
        val res = this - other
        this.v = res.v
    }

    operator fun timesAssign(other: Co) {
        val res = this * other
        this.v = res.v
    }

    operator fun divAssign(other: Co) {
        val res = this / other
        this.v = res.v
    }

    override fun toString(): String = v.toString()
}

fun coFromInt(value: Int): Co =
    Co(((value.toLong() % M + M) % M))

fun coFromLong(value: Long): Co =
    Co(((value % M + M) % M))

fun coFromULong(value: Long): Co =
    Co(((value % M + M) % M))

class Env(val k: Int, val d: Int, val memo: Array<Array<Co?>>) {
    fun need(n: Int): Co {
        memo[n][0]?.let { return it }
        var sum = Co(0L)
        for (i in 1..k) {
            if (n >= i) {
                if (i >= d) sum += all(n - i)
                else sum += need(n - i)
            }
        }
        memo[n][0] = sum
        return sum
    }

    fun all(n: Int): Co {
        memo[n][1]?.let { return it }
        var sum = Co(0L)
        for (i in 1..k) {
            if (n >= i) sum += all(n - i)
        }
        memo[n][1] = sum
        return sum
    }
}

class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c = readByte()
        while (c <= 32 && c >= 0) c = readByte()
        while (c > 32) {
            sb.append(c.toChar())
            c = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

