    val scan = FastScanner()
    val n = scan.nextInt()
    val k = scan.nextInt()
    val d = scan.nextInt()
    val memo = Array(n + 1) { Array<Co?>(2) { null } }
    val env = Env(k, d, memo)
    memo[0][1] = coFromInt(1)
    val out = PrintWriter(System.out)
    out.println(env.need(n).toString())
    out.flush()
}

